3. Calculate and print the number of days, hours, and minutes a user session lasted:
Instant loginTime = Instant.parse('2026-03-20T08:30:00Z');
Instant logoutTime = Instant.parse('2026-03-20T17:45:30Z');

items.a:
Duration session = Duration.between(loginTime, logoutTime);
long hours   = session.toHours();
long minutes = session.toMinutesPart(); // Java 9+
long seconds = session.toSecondsPart(); // Java 9+
System.out.printf('Session: %d hours, %d minutes, %d seconds%n', hours, minutes, seconds);
// Output: Session: 9 hours, 15 minutes, 30 seconds
// Note: toHours() gives TOTAL hours (9), toMinutesPart() gives only the MINUTES PART (15), not total minutes (555). Using toMinutes() would give 555, which is total minutes — not what we want for human display.

ZonedDateTime departure = ZonedDateTime.of(
    LocalDate.of(2026, 3, 20), LocalTime.of(22, 0),
    ZoneId.of('Asia/Kolkata'));
ZonedDateTime arrival = ZonedDateTime.of(
    LocalDate.of(2026, 3, 21), LocalTime.of(5, 0),
    ZoneId.of('Europe/London'));
Duration flightTime = Duration.between(departure, arrival);
System.out.println('Flight duration: ' + flightTime.toHours() + 'h ' + flightTime.toMinutesPart() + 'm');
// IST is UTC+5:30, BST is UTC+1:00
// Departure: 22:00 IST = 16:30 UTC
// Arrival:   05:00 BST = 04:00 UTC (next day)
// Duration: 04:00 UTC - 16:30 UTC(previous day) = 11.5 hours
// Output: Flight duration: 11h 30m

public List<LocalDate> getMondaysInMonth(int year, int month) {
    LocalDate firstDay = LocalDate.of(year, month, 1);
    LocalDate firstMonday = firstDay.with(
        TemporalAdjusters.nextOrSame(DayOfWeek.MONDAY));
    List<LocalDate> mondays = new ArrayList<>();
    LocalDate current = firstMonday;
    while (current.getMonthValue() == month) {
        mondays.add(current);
        current = current.plusWeeks(1);
    }
    return mondays;
}
// Usage: getMondaysInMonth(2026, 3) → [2026-03-02, 2026-03-09, 2026-03-16, 2026-03-23, 2026-03-30]

