private static final ZoneId IST = ZoneId.of('Asia/Kolkata');

public boolean isSameDay(Instant a, Instant b) {
    LocalDate dateA = a.atZone(IST).toLocalDate();
    LocalDate dateB = b.atZone(IST).toLocalDate();
    return dateA.isEqual(dateB);
}
// Key insight: 2026-03-20T23:00:00Z and 2026-03-21T00:00:00Z are the SAME day in IST
// (23:00 UTC = 04:30 IST next day — wait, that's +5:30)
// 2026-03-20T23:00:00Z = 2026-03-21T04:30:00 IST → March 21
// 2026-03-20T18:30:00Z = 2026-03-21T00:00:00 IST → March 21 (midnight IST)
// Without converting to IST, the same 'day' comparison would be wrong for UTC timestamps near midnight IST.
